    p['status'] = 'offered'
    key = {'floor_too_much': 'floor_offer', 'below_floor': 'below_floor'}.get(kind, 'offer')
    txt = say(key, amount=money(amt), date=sp(d), name=p['name'])
    if named and key == 'offer':
        txt = say('offer_named', amount=money(amt), date=sp(d), name=p['name'])
